#include <vector>
#include <deque>
#include <tuple>

using namespace std;

class Solution {
public:
    int minCost(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        const int INF = 1e9;
        vector<vector<int>> dist(m, vector<int>(n, INF));
        dist[0][0] = 0;

        deque<tuple<int, int, int>> dq;
        dq.push_back({0, 0, 0});
        const int dirs[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!dq.empty()) {
            auto [r, c, cost] = dq.front();
            dq.pop_front();

            if (r == m - 1 && c == n - 1) return cost;
            if (cost > dist[r][c]) continue;

            for (int d = 1; d <= 4; ++d) {
                int nr = r + dirs[d - 1][0];
                int nc = c + dirs[d - 1][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int weight = (grid[r][c] == d) ? 0 : 1;
                    if (cost + weight < dist[nr][nc]) {
                        dist[nr][nc] = cost + weight;
                        if (weight == 0) {
                            dq.push_front({nr, nc, cost});
                        } else {
                            dq.push_back({nr, nc, cost + 1});
                        }
                    }
                }
            }
        }
        return dist[m - 1][n - 1];
    }
};

import java.util.Deque;
import java.util.ArrayDeque;
import java.util.Arrays;

class Solution {
    public int minCost(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;

        Deque<int[]> dq = new ArrayDeque<>();
        dq.offer(new int[]{0, 0, 0});
        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!dq.isEmpty()) {
            int[] curr = dq.pollFirst();
            int r = curr[0], c = curr[1], cost = curr[2];

            if (r == m - 1 && c == n - 1) return cost;
            if (cost > dist[r][c]) continue;

            for (int d = 1; d <= 4; d++) {
                int nr = r + dirs[d - 1][0];
                int nc = c + dirs[d - 1][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int weight = (grid[r][c] == d) ? 0 : 1;
                    if (cost + weight < dist[nr][nc]) {
                        dist[nr][nc] = cost + weight;
                        if (weight == 0) {
                            dq.offerFirst(new int[]{nr, nc, cost});
                        } else {
                            dq.offerLast(new int[]{nr, nc, cost + 1});
                        }
                    }
                }
            }
        }
        return dist[m - 1][n - 1];
    }
}

